import{getWrapper as t}from"fetch";export async function getFriendRequestToast(){return await t({url:"/friend/getFriendRequestToast",$loadingDiv:null,loading:"",dataHandler:t=>{const e=document.createElement("div");e.innerHTML=t,document.getElementById("toastsDiv").appendChild(e);const n=document.getElementById("friendRequestToast");if(n){new bootstrap.Toast(n).show()}}})}export function createToast(t,e="primary",n="bi-info-circle",o=5e3){let a=document.querySelector(".toast-container");a||(a=document.createElement("div"),a.className="toast-container position-fixed bottom-0 end-0 p-3",document.body.appendChild(a));const s="toast-"+Date.now(),i=`\n        <div id="${s}" class="toast align-items-center text-bg-${e} border-0" role="alert" aria-live="assertive" aria-atomic="true">\n            <div class="d-flex">\n                <div class="toast-body">\n                    <i class="bi ${n} me-2"></i>${t}\n                </div>\n                <button type="button" class="btn-close btn-close-white me-2 m-auto" data-bs-dismiss="toast" aria-label="Close"></button>\n            </div>\n        </div>\n    `;a.insertAdjacentHTML("beforeend",i);const d=document.getElementById(s),r=new bootstrap.Toast(d,{autohide:!0,delay:o});return r.show(),d.addEventListener("hidden.bs.toast",()=>{d.remove()}),r}